export const getReportResultUrl = (gameId: string,) => {




  return `/api/games/${gameId}/results`
}

/**
 * Reports a final score. The result is not counted toward standings until
 * the opposing GM confirms it. Append-only — a correction supersedes the
 * previous result and must carry a supersede_reason.
 * @summary Report a result for a game
 */
export const reportResult = async (gameId: string,
    resultInput: ResultInput, options?: RequestInit): Promise<GameResult> => {

  return customFetch<GameResult>(getReportResultUrl(gameId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(resultInput)
  }
);}





export const getReportResultMutationOptions = <TError = ErrorType<Problem>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof reportResult>>, TError,{gameId: string;data: BodyType<ResultInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof reportResult>>, TError,{gameId: string;data: BodyType<ResultInput>}, TContext> => {

const mutationKey = ['reportResult'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof reportResult>>, {gameId: string;data: BodyType<ResultInput>}> = (props) => {
          const {gameId,data} = props ?? {};

          return  reportResult(gameId,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type ReportResultMutationResult = NonNullable<Awaited<ReturnType<typeof reportResult>>>
    export type ReportResultMutationBody = BodyType<ResultInput>
    export type ReportResultMutationError = ErrorType<Problem>

    /**
 * @summary Report a result for a game
 */
export const useReportResult = <TError = ErrorType<Problem>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof reportResult>>, TError,{gameId: string;data: BodyType<ResultInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof reportResult>>,
        TError,
        {gameId: string;data: BodyType<ResultInput>},
        TContext
      > => {
      return useMutation(getReportResultMutationOptions(options));
    }

export const getConfirmResultUrl = (resultId: string,) => {




  return `/api/results/${resultId}/confirm`
}

/**
 * Confirmation must come from a different user than the reporter. Self-confirmation
 * is rejected. Supply the If-Match header with the result's version to prevent
 * racing GMs from silently overwriting each other.
 * @summary Confirm or dispute a reported result
 */
export const confirmResult = async (resultId: string,
    confirmInput: ConfirmInput, options?: RequestInit): Promise<GameResult> => {

  return customFetch<GameResult>(getConfirmResultUrl(resultId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(confirmInput)
  }
);}





export const getConfirmResultMutationOptions = <TError = ErrorType<Problem>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof confirmResult>>, TError,{resultId: string;data: BodyType<ConfirmInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof confirmResult>>, TError,{resultId: string;data: BodyType<ConfirmInput>}, TContext> => {

const mutationKey = ['confirmResult'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof confirmResult>>, {resultId: string;data: BodyType<ConfirmInput>}> = (props) => {
          const {resultId,data} = props ?? {};

          return  confirmResult(resultId,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type ConfirmResultMutationResult = NonNullable<Awaited<ReturnType<typeof confirmResult>>>
    export type ConfirmResultMutationBody = BodyType<ConfirmInput>
    export type ConfirmResultMutationError = ErrorType<Problem>

    /**
 * @summary Confirm or dispute a reported result
 */
export const useConfirmResult = <TError = ErrorType<Problem>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof confirmResult>>, TError,{resultId: string;data: BodyType<ConfirmInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof confirmResult>>,
        TError,
        {resultId: string;data: BodyType<ConfirmInput>},
        TContext
      > => {
      return useMutation(getConfirmResultMutationOptions(options));
    }

